mapper.select:
select d.TRADE_ID as tradeId, /**交易编号**/
acct.ACCT_SUBJECT_ID as prodId, acct.ACCT_SUBJECT_NAME as prodAbbr, SAI.ACCT_NO AS acctNo, /**资金账户号*/ SAI.ACCT_NAME as acctName, /** 资金账户名 **/ to_char(d.VDATE,'yyyy-mm-dd') as vDate, /** 上次收息日(起息日)**/ to_char(d.MDATE,'yyyy-mm-dd') as mDate, /** 本次收息日（到期日）**/ NVL(bb.o_amt,0) as theoryIntAmt, /** 理论利息(计算)**/ d.trade_Amt as realIntAmt, /** 实际利息（利息总额--现金流）**/ d.BUSI_TYPE as busiTypeCode, /**业务类型Code**/ d.BUSI_TYPE as busiType, /**业务类型**/ d.TRADE_STATUS as tradeStatus, /**交易状态（根据信息有效）**/ d.CCY as ccyCode,/**交易币种Code**/ d.CCY as ccy/**交易币种**/ FROM trd_PRODUCT_DEAL d LEFT JOIN STL_CAPACCT_INFO SAI ON D.FINPROD_ID=SAI.ACCT_NO
LEFT JOIN TRD_PRODUCT_DEAL_ADD EXT ON D.TRADE_ID=EXT.TRADE_ID /**活期存款收息获取理论利息 根据bok_balance表的账套id,固定编码.以及date-1*/
/**【一体化注释：金融产品交易附属表TRD_PRODUCT_DEAL_ADD去除对PROD_ID字段】**/ /**LEFT JOIN BOK_BOOKSET BSET ON EXT.PROD_ID=BSET.ACCT_SUBJECT_ID**/ LEFT JOIN BOK_BOOKSET BSET ON '不进行关联'=BSET.ACCT_SUBJECT_ID
LEFT JOIN BOK_BALANCE BB ON BSET.BOOKSET_ID=BB.BOOKSET_ID AND BB.SUBJECT_NO='12040101' AND BB.BALANCE_DATE =d.trade_date - 1 left JOIN FIN_PRODUCT zc ON zc.finprod_id = EXT.PROD_ID
left join TRD_PRODUCT_DEAL_ADD e on d.trade_id = e.trade_id
inner join BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = d.TRADE_ID inner join BOK_BOOKSET book on deal.BOOKSET_ID = book.BOOKSET_ID inner join BOK_ACCT_SUBJECT_INFO acct on acct.ACCT_SUBJECT_ID = book.ACCT_SUBJECT_ID and acct.ACCT_SUBJECT_TYPE = book.ACCT_SUBJECT_TYPE left join TRD_TRADE_FEE_DETAIL tdf on tdf.trade_id = d.trade_id and tdf.fee_type = 'B09' where d.TRADE_ID = #{tradeId}
and acct.ACCT_SUBJECT_ID = #{prodId}

select d.TRADE_ID as tradeId, /**交易编号**/ to_char(fin.EFF_DATE,'yyyy-mm-dd') as effDate,/**计提日(生效日期)**/ fin.BASIS as basis,/**计提基数（计算基础）**/ fin.YIELD as yield,/**利率(生效利率)**/ d.INT_AMT as intAmt,/**利息金额(利息总额)**/ row_number() over (partition by d.TRADE_ID order by fin.EFF_DATE) as num from trd_PRODUCT_DEAL d inner join FIN_PRODUCT zc on zc.finprod_id = d.finprod_id
left join TRD_PRODUCT_DEAL_ADD e on d.trade_id = e.trade_id
/**【一体化注释：金融产品交易附属表TRD_PRODUCT_DEAL_ADD去除对PROD_ID字段】**/ /**left join FIN_PRODUCT cp on cp.finprod_id = e.prod_id**/
left join TRD_TRADE_FEE_DETAIL tdf on tdf.trade_id = d.trade_id and tdf.fee_type = 'B09' left join FIN_CASH_CALC_RULE fin on fin.FINPROD_ID = d.FINPROD_ID /**现金流计算规则表**/ where 1=1
and d.TRADE_ID = #{tradeId}
